// https://<host>/p/<slug>, optionally with a trailing slash, query or fragment. No userinfo or port.
const postSlug = (link, host) => {
  const m = /^https:\/\/([A-Za-z0-9.-]+)\/p\/([a-z0-9-]{1,200})\/?(?:[?#][^\s]*)?$/.exec(String(link).trim());
  return m && m[1].toLowerCase() === host ? m[2] : null;
};
// Narrow capture adapter for one public Substack post (#915). Same rules as the Mastra track (#920).
// The signed transcript link is used for exactly one request inside this node and never leaves it:
// nothing this node outputs (and so nothing n8n stores in execution history) contains it.
const MAX = 5000000;
const CDN_HOST = 'substackcdn.com';
const fail = (code, message) => { throw new Error(`${code}: ${message}`); };
const input = $json;
const host = input.publicationHost;
const slug = postSlug(input.url, host);
if (!slug) fail('wrong-publication', 'not a post URL on the allowed publication');
const fixture = typeof input.store === 'string' && input.store.startsWith('fixture-') && input.fixturePost !== undefined;
const get = async (url) => {
  let r;
  try {
    r = await this.helpers.httpRequest({ url, returnFullResponse: true, json: false, encoding: 'text', maxRedirects: 0,
      timeout: 20000, ignoreHttpStatusErrors: true, maxContentLength: MAX, maxBodyLength: MAX, headers: { accept: 'application/json' } });
  } catch (e) { return { status: null, body: '', error: String(e.message || e).replace(/https?:\/\/\S+/g, '[url]').slice(0, 200) }; }
  const body = typeof r.body === 'string' ? r.body : Buffer.isBuffer(r.body) ? r.body.toString('utf8') : JSON.stringify(r.body ?? '');
  return { status: r.statusCode, body };
};
// Removes signed URLs (ephemeral credentials) from retained JSON.
const sanitize = (v) => {
  if (Array.isArray(v)) return v.map(sanitize);
  if (v && typeof v === 'object')
    return Object.fromEntries(Object.entries(v).map(([k, x]) =>
      typeof x === 'string' && (k === 'cdn_url' || /^https?:\/\/[^ ]*[?&](Expires|Signature|X-Amz-Signature|Key-Pair-Id)=/i.test(x)) ? [k, '[signed-url-removed]'] : [k, sanitize(x)]));
  return v;
};
let post;
if (fixture) post = input.fixturePost;
else {
  const r = await get(`https://${host}/api/v1/posts/${encodeURIComponent(slug)}`);
  if (r.status === null) fail('post-unavailable', `post endpoint unreachable (${r.error})`);
  if (r.status === 404) fail('post-not-found', 'no such post');
  if (r.status !== 200) fail('post-unavailable', `post endpoint returned ${r.status}`);
  if (r.body.length > MAX) fail('invalid-post', 'response too large');
  try { post = JSON.parse(r.body); } catch { fail('invalid-post', 'post response is not JSON'); }
}
if (!post || typeof post !== 'object' || !(/^\d{1,15}$/.test(String(post.id))) || typeof post.slug !== 'string' || post.slug.toLowerCase() !== slug)
  fail('invalid-post', 'unexpected post shape');
if ((post.audience ?? 'everyone') !== 'everyone') fail('restricted', 'post is not public');
const warnings = [];
let transcriptJoined = null, rawTranscript = null, transcriptUpload = null;
const which = ['podcastUpload', 'videoUpload'].find((k) => post[k]?.transcription?.status === 'transcribed' && post[k].transcription.cdn_url);
if (which) {
  const segsFrom = (body) => {
    let s; try { s = JSON.parse(body); } catch { return null; }
    if (!Array.isArray(s) || s.length === 0 || !s.every((x) => x && typeof x.text === 'string' && typeof x.start === 'number' && typeof x.end === 'number')) return null;
    return s;
  };
  let body = null;
  if (fixture) body = input.fixtureTranscript === undefined || input.fixtureTranscript === null ? null : JSON.stringify(input.fixtureTranscript);
  else {
    const m = /^https:\/\/([^/?#@:]+)\//.exec(String(post[which].transcription.cdn_url));
    if (!m || m[1] !== CDN_HOST) warnings.push('supplied-transcript-host-not-allowed');
    else {
      const t = await get(post[which].transcription.cdn_url);
      if (t.status === 200 && t.body.length <= MAX) body = t.body;
      else warnings.push('supplied-transcript-unavailable');
    }
