  text = htmlToText(post.body_html);
  if (medium === 'audio' || medium === 'video') warnings.push('text-is-article-description-not-transcript');
}
// The contract's text normalisation: NFC, LF line endings, no trailing whitespace.
text = text.replace(/\r\n/g, '\n').normalize('NFC').trimEnd();
