const bylines = (post.publishedBylines ?? []).map((b) => (b?.name ?? '').trim()).filter(Boolean);
const bundle = validateBundle({
  schema: 'source-bundle-v1', item: `substack:${publication}:${post.id}`, postId: String(post.id), slug: f.slug,
  url: `https://${host}/p/${f.slug}`, title: String(post.title ?? '').trim(), publishedAt: iso(post.post_date),
  updatedAt: iso(post.updated_at), author: bylines.length === 1 ? bylines[0] : null, medium,
  audience: post.audience ?? 'everyone', mediaUploadId: mediaUploadId === null ? null : String(mediaUploadId), textSource, text,
