  rawTranscript: f.rawTranscript, warnings, textSource, textChars: text.length,
  captureMeta: { platform: 'n8n', canonicalUrl: bundle.url, fetchedAt: f.fetchedAt, source: f.source, execution: $execution.id } } };

const r = $json.result;
const b = $('Build bundle').item.json;
return { json: { ok: true, httpStatus: 200, ...r, textSource: b.textSource, textChars: b.textChars, warnings: b.warnings } };

// A fetch failure (not an evidence finding): nothing is saved. Permanent failures leave the capture queue.
const message = String($json.error?.message ?? $json.error ?? 'capture failed').replace(/https?:\/\/\S+/g, '[url]').slice(0, 500);
